CREATE TABLE IF NOT EXISTS "repo_publication_receipt" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "receipt_no" varchar(64) NOT NULL,
    "supplier_id" bigint NOT NULL,
    "supplier_name_snapshot" varchar(128) DEFAULT NULL,
    "warehouse_id" bigint NOT NULL,
    "warehouse_name_snapshot" varchar(128) DEFAULT NULL,
    "status" int NOT NULL DEFAULT 10,
    "expected_count" int NOT NULL DEFAULT 0,
    "received_count" int NOT NULL DEFAULT 0,
    "allocated_count" int NOT NULL DEFAULT 0,
    "submit_time" timestamp DEFAULT NULL,
    "close_time" timestamp DEFAULT NULL,
    "close_reason" varchar(512) DEFAULT NULL,
    "remark" varchar(512) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '刊物收货单';

CREATE TABLE IF NOT EXISTS "repo_publication_receipt_item" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "receipt_id" bigint NOT NULL,
    "supplier_id" bigint NOT NULL,
    "warehouse_id" bigint NOT NULL,
    "window_id" bigint NOT NULL,
    "window_name_snapshot" varchar(128) DEFAULT NULL,
    "offer_id" bigint NOT NULL,
    "offer_sku_id" bigint NOT NULL,
    "spu_id" bigint NOT NULL,
    "sku_id" bigint NOT NULL,
    "product_name_snapshot" varchar(255) DEFAULT NULL,
    "product_sku_name_snapshot" varchar(255) DEFAULT NULL,
    "isbn" varchar(64) DEFAULT NULL,
    "issue_id" bigint DEFAULT NULL,
    "issue_no" int NOT NULL,
    "issue_name" varchar(128) DEFAULT NULL,
    "expected_count" int NOT NULL DEFAULT 0,
    "received_count" int NOT NULL DEFAULT 0,
    "allocated_count" int NOT NULL DEFAULT 0,
    "remark" varchar(512) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '刊物收货明细';

CREATE TABLE IF NOT EXISTS "repo_publication_receipt_allocation" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "receipt_item_id" bigint NOT NULL,
    "delivery_batch_id" bigint NOT NULL,
    "allocated_count" int NOT NULL,
    "operator_user_id" bigint DEFAULT NULL,
    "delivery_time" timestamp NOT NULL,
    "remark" varchar(512) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
) COMMENT '刊物出库占用流水';
